function CheckLettered() {
var f = document.forms[0]
if( f.ODLetMsg.value == "" ) {
  alert( "You must enter the message text for a strip insert.")
  f.ODLetMsg.focus()
  return false
}   
if( f.ODLetStyle.value == "") {
   alert("You must select a type style for this strip insert.")
   f.ODLetStyle.focus()
   return false
   }
if( f.ODFormat.value == "") {
   alert("You must select a lettering format for this strip insert.")
   f.ODFormat.focus()
   return false
   }
if( f.ODLetColor.value == "") {
   alert("You must select a font color for this strip insert.")
   f.ODLetColor.focus()
   return false
   }
if( f.ODQty == "") {
   alert("You must enter a quantity for this strip insert or zero to delete this line item.")
   f.ODQty.focus()
   return false ;
   }
x = f.ADACompliant_1.length - 1;
while(x > 0) {
/*Check if anything besides the first choice is selected*/
if (f.ADACompliant_1[x].selected) {
break;
}
x-=1;
}

if( x == 0) {
   alert("You must indicate whether this insert should be ADA Compliant.")
   f.ADACompliant_1.focus()
   return false ;
}  
if( x == 1  && f.ADAMsg_1.value == "") {
	alert("If ADA Compliant, please enter a message.")
	f.ADAMsg_1.focus()
	return false ;
	}
}

function CheckBlank() {
var f = document.forms[0]

if( f.Color.value == "") {
   alert("You must select a color for this blank strip.")
