if( f.BlankQty == "") {
   alert("You must enter a quantity for this blank strip or zero to delete this line item.")
   f.BlankQty.focus()
   return false ;
   }
}

function CheckFrame() {
var f = document.forms[0]

if( f.FrameQty == "") {
   alert("You must enter a quantity for this frame or zero to delete this line item.")
   f.FrameQty.focus()
   return false ;
