   alert("You must select a color for this frame.")
   f.Color_1.focus()
   return false ;
   }
if( f.Shape.value == "") {
   alert("You must select a shape for this frame.")
   f.Shape.focus()
   return false ;
   }
fr = f.ADACompliant.length - 1;
while(fr > 0) {
/*Check if anything besides the first choice is selected*/
if (f.ADACompliant[fr].selected) {
break;
}
fr-=1;
}

if( fr == 0) {
   alert("You must indicate whether this frame should be ADA Compliant.")
