var f = document.forms[0];
var now = new Date;
var mon = now.getMonth;
var yr = now.getYear;

//We need some basic name and email info to process.
if( f.WebName.value == "" ) {
	alert("Please enter your first and last names to assist us in contacting you regarding this order.")
	f.isSubmitted.value="No"   	
	f.WebName.focus()
	f.WebName.select()
   	return false
}

if( f.WebEmail.value == "" ) {
	alert("Please enter your email address to assist us in contacting you regarding this order.")
	f.isSubmitted.value="No"
   	f.WebEmail.focus()
   	return false
}
   var emailok = validEmail(f.WebEmail.value)
	if (!emailok) {
		alert("Your email address appears to be invalid.  Please check and reenter a valid email address")
		f.isSubmitted.value="No"
		f.WebEmail.focus()
		f.WebEmail.select()
	return false
}

if( f.WebPhone.value == "" || f.WebArea.value == "" || f.WebExchange.value == "") {
	alert("Your phone number does not appear to be entered correctly. Please re-enter your phone number to assist us in contacting you regarding this order.")
	f.isSubmitted.value="No"
   	f.WebArea.focus()
   	f.WebArea.select()
   	return false
}

//Billing information must be entered.
if( f.OHBill_CustNam.value == "" ) {
	alert("Please enter company name or your name in the Bill To section.")
	f.isSubmitted.value="No"
   	f.OHBill_CustNam.focus()
   	return false
}

if( f.OHBill_Add1.value == "" ) {
	alert("Please enter your billing address in the Bill To section.")
	f.isSubmitted.value="No"
   	f.OHBill_Add1.focus()
   	return false
}

if( f.OHBill_City.value == "" || f.OHBill_ZIP.value == "") {
	alert("Please be certain that city, state, and ZIP code information is entered in the Bill To section.")
	f.isSubmitted.value="No"
   	f.OHBill_City.focus()
   	return false
}

if( f.OHBill_Phone.value == "" ) {
	alert("Please enter your phone number in the Bill To section.")
	f.isSubmitted.value="No"
   	f.OHBill_Phone.focus()
   	return false
}
//We must have either a credit card number or a PO number.
cclen = f.OHCCNum.value.length;
polen = f.OHPONumber.value.length;

if( cclen == 0 && polen == 0) {
	alert("Please enter either a purchase order number or a credit card number.")
	f.isSubmitted.value="No"
   	f.OHCCType.focus()
   	return false
}

//if( cclen != 0 && polen != 0) {
//	alert("Please enter either a purchase order number or a credit card number but not both.")
//	f.isSubmitted.value="No"
//	f.OHCCNum.focus()
//	return false
//}

//if the user entered one or the other and there is no po number, validate the credit card info
if( polen == 0) {

	len = f.OHCCType.length - 1;
	while(len > 0) {
/*Check if anything besides the first choice is selected*/
	if (f.OHCCType[len].selected) {
	break;	
	}
	len-=1;
	}

	if( len == 0 && cclen != 0) {
		alert("If you are using a credit card, please enter the card type.")
		f.isSubmitted.value="No"
		f.OHCCType.focus()
		return false
	}

	if( len != 0 && cclen == 0) {
		alert("If you are using a credit card, please enter the card number.")
		f.isSubmitted.value="No"
		f.OHCCNum.focus()
		return false
	}
	molen = f.OHCCExpMo.length - 1;
	while(molen > 0) {
/*Check if anything besides the first choice is selected*/
	if (f.OHCCExpMo[molen].selected) {
	break;
	}
	molen-=1;
	}
	if (cclen != 0 && molen == 0) {
		alert("Please enter the Card's Expiration Month.");
		f.isSubmitted.value="No"
		f.OHCCExpMo.focus();
		return false;
	}
	yrlen = f.OHCCExpYr.length - 1;
	while(yrlen > 0) {
	/*Check if anything besides the first choice is selected*/
	if (f.OHCCExpYr[yrlen].selected) {
	break;
	}
	yrlen-=1;
	}
	if (cclen != 0 && yrlen == 0) {
		alert("Please enter the Card's Expiration Year.");
		f.isSubmitted.value="No"
		f.OHCCExpYr.focus();
		return false;
	}
	if( len != 0 && cclen != 0) {
		var mod0 = luhnCheck(f.OHCCNum.value)
		if (!mod0) {
			f.isSubmitted.value="No";
			f.OHCCNum.focus();
			return false;
		 }
		else {
			f.OHCCNum.value == f.OHCCNum.value;
		}
	}	

//Validate the CVV code
		var result = validateCvvCode();
		if (!result) {
			alert('Invalid CVV Number');
			f.OHCVVNum.focus();
			return false;
	}		

}

//Determine if this order has been submitted previously.
if (f.isSubmitted.value=="Yes") {
	alert("You have already submitted this order.  You cannot submit it again");
	return false;
	}

//Here, we will just warn the user that Ship To info was not entered and ask them to check the confirmation page carefully.
if( f.OHShip_CustNam.value == "" && f.OHShip_Add1.value == "" && f.OHShip_City.value == "" && f.OHShip_State.value == "") {
	alert("Ship To information will be the same as Bill To information.  Please check the confirmation page carefully before submitting this order.")
