/*************************************************************************\
CheckCardNumber(form)
function called when users click the "check" button.
\*************************************************************************/
function CheckCardNumber() {
var form = document.forms[0];

card = form.OHCCType.options[form.OHCCType.selectedIndex].value;
var tmpyear = form.OHCCExpYr.value;
var tmpmonth = form.OHCCExpMo.value;

var retval = eval(card + ".checkOHCCNum(\"" + form.OHCCNum.value + "\", " + tmpyear + ", " + tmpmonth + ");");
cardname = "";

if (retval)
alert(" ");
else {
// The cardnumber has the valid luhn checksum, but we want to know which
// cardtype it belongs to.
for (var n = 0; n < Cards.size; n++) {
if (Cards[n].checkOHCCNum(form.OHCCNum.value, tmpyear, tmpmonth)) {
cardname = Cards[n].getCardType();
break;
   }
}
if (cardname.length > 0) {
alert("This looks like a " + cardname + " number, not a " + card + " number.");
}
else {
alert("This credit card number is not valid.");
      }
   }
}
