function validEmail(email) {
	invalidChars = " / : , ; "

	if (email == " ") {
		alert("Blank email address")
		return false
	}
	for (i = 0; i < invalidChars.length ; i++) {
	badChar = invalidChars.charAt(i)
		if (email.indexOf (badChar, 0) != -1) {
			//alert("Bad characters in email address")
			return false
		}
	}
	atPos = email.indexOf ("@",1)
	if (atPos == -1) {
		//alert("No @ character in email address")
		return false
	}
	if (email.indexOf("@", atPos + 1) != -1) {
		//alert("Too many @ characters in email address")
		return false
	}
	periodPos = email.indexOf("." , atPos)
	if (periodPos == -1) {
		//alert("Must be at least one period after the @ character in the email address")
		return false
	}
	if (periodPos + 3 > email.length) {
		//alert("Must be at least two characters after the period in the email address")
		return false
	}
	return true
}
